type Row {
    name: Text = "";
    pts: Int = 0;
    gd: Int = 0;
    gf: Int = 0;
    rank: Int = 0;
}
fn main() -> Void {
    let doc: ToonDoc;
    fx { doc = toon_parse_file("league.json"); }
    let root: ToonNode = toon_root(doc);
    let teams: ToonNode = toon_key(root, "teams");
    let rows: Row[] = [];
    fx {
        loop i in 0..toon_len(teams) {
            let t: ToonNode = toon_at(teams, i);
            let nm: Text = toon_get_text_or(t, "name", "?");
            let won: Int = toon_get_int_or(t, "won", 0);
            let drawn: Int = toon_get_int_or(t, "drawn", 0);
            let gf: Int = 0;
            let ga: Int = 0;
            if toon_has_key(t, "stats") {
                let st: ToonNode = toon_key(t, "stats");
                gf = toon_get_int_or(st, "gf", 0);
                ga = toon_get_int_or(st, "ga", 0);
            }
            rows = rows + [new Row { name: nm, pts: won * 3 + drawn, gd: gf - ga, gf: gf, rank: 0 }];
        }
        toon_close(doc);
    }
    loop i in 0..length(rows) {
        loop j in 0..(length(rows) - 1 - i) {
            let a: Row = rows[j];
            let b: Row = rows[j + 1];
            let swap: Bool = false;
            if b.pts > a.pts { swap = true; }
            if b.pts == a.pts {
                if b.gd > a.gd { swap = true; }
                if b.gd == a.gd {
                    if b.gf > a.gf { swap = true; }
                    if b.gf == a.gf {
                        if b.name < a.name { swap = true; }
                    }
                }
            }
            if swap { rows[j] = b; rows[j + 1] = a; }
        }
    }
    let rank: Int = 1;
    loop i in 0..length(rows) {
        if i > 0 {
            let p: Row = rows[i - 1];
            let c: Row = rows[i];
            if c.pts != p.pts || c.gd != p.gd || c.gf != p.gf { rank = i + 1; }
        }
        rows[i].rank = rank;
    }
    fx {
        loop i in 0..length(rows) {
            println(rows[i].rank, ". ", rows[i].name, " pts=", rows[i].pts,
                    " gd=", rows[i].gd, " gf=", rows[i].gf);
        }
    }
    let tied: Int = 0;
    loop i in 1..length(rows) { if rows[i].rank == rows[i - 1].rank { tied = tied + 1; } }
    fx { println("teams=", length(rows), " tiedPairs=", tied, " topRank=", rows[0].rank); }
}

fn main() -> Void {
    let src: Text = "set x = 12; # note\nsay \"hi there\"; say \"bad";
    let kinds: Text[] = [];
    let vals: Text[] = [];
    let cols: Int[] = [];
    let lines: Int[] = [];
    let line: Int = 1;
    let col: Int = 1;
    let i: Int = 0;
    let unterminated: Int = 0;
    loop guard in 0..string_len(src) {
        if i < string_len(src) {
            let c: Text = src[i..i + 1];
            if string_eq(c, "\n") { line = line + 1; col = 1; i = i + 1; }
            else {
                if string_eq(c, " ") { col = col + 1; i = i + 1; }
                else {
                    if string_eq(c, "#") {
                        loop k in i..string_len(src) {
                            if i < string_len(src) && !string_eq(src[i..i + 1], "\n") { i = i + 1; col = col + 1; }
                        }
                    } else {
                        if string_eq(c, "\"") {
                            let startCol: Int = col;
                            let startLine: Int = line;
                            let body: Text = "";
                            let closed: Bool = false;
                            i = i + 1; col = col + 1;
                            loop k in i..string_len(src) {
                                if !closed && i < string_len(src) {
                                    let d: Text = src[i..i + 1];
                                    if string_eq(d, "\"") { closed = true; i = i + 1; col = col + 1; }
                                    else { body = body + d; i = i + 1; col = col + 1; }
                                }
                            }
                            if closed {
                                kinds = kinds + ["str"]; vals = vals + [body];
                                cols = cols + [startCol]; lines = lines + [startLine];
                            } else { unterminated = unterminated + 1; }
                        } else {
                            if string_eq(c, ";") {
                                kinds = kinds + ["semi"]; vals = vals + [";"];
                                cols = cols + [col]; lines = lines + [line];
                                i = i + 1; col = col + 1;
                            } else {
                                let startCol2: Int = col;
                                let word: Text = "";
                                loop k in i..string_len(src) {
                                    if i < string_len(src) {
                                        let e: Text = src[i..i + 1];
                                        if !string_eq(e, " ") && !string_eq(e, ";") && !string_eq(e, "\n") && !string_eq(e, "#") && !string_eq(e, "\"") {
                                            word = word + e; i = i + 1; col = col + 1;
                                        }
                                    }
                                }
                                if string_len(word) > 0 {
                                    kinds = kinds + ["word"]; vals = vals + [word];
                                    cols = cols + [startCol2]; lines = lines + [line];
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    fx {
        loop k in 0..length(kinds) {
            println(lines[k], ":", cols[k], " ", kinds[k], " '", vals[k], "'");
        }
        println("tokens=", length(kinds), " unterminated=", unterminated);
    }
}

@pure
fn roundHalfUp(cents10: Int) -> Int {
    let neg: Bool = cents10 < 0;
    let v: Int = cents10;
    if neg { v = 0 - v; }
    let q: Int = v / 10;
    let r: Int = v - q * 10;
    if r >= 5 { q = q + 1; }
    if neg { ret 0 - q; }
    ret q;
}
@pure
fn money(cents: Int) -> Text {
    let neg: Bool = cents < 0;
    let v: Int = cents;
    if neg { v = 0 - v; }
    let whole: Int = v / 100;
    let frac: Int = v - whole * 100;
    let fs: Text = int_to_text(frac);
    if frac < 10 { fs = "0" + fs; }
    let body: Text = int_to_text(whole) + "." + fs;
    if neg { ret "(" + body + ")"; }
    ret body;
}
fn main() -> Void {
    let labels: Text[] = ["open", "fee", "refund", "adj", "close"];
    let tenths: Int[] = [125000, -3335, 22225, -1, -50005];
