}

@pure
fn luhnValid(digits: Int[]) -> Bool {
    let sum: Int = 0;
    let n: Int = length(digits);
    loop k in 0..n {
        let idx: Int = n - 1 - k;
        let d: Int = digits[idx];
        if k % 2 == 1 {
            d = d * 2;
            if d > 9 { d = d - 9; }
        }
        sum = sum + d;
    }
    ret sum % 10 == 0;
}
@pure
fn toDigits(s: Text) -> Int[] {
    let out: Int[] = [];
    loop i in 0..string_len(s) {
        let c: Int = ord(s[i]);
        if c >= 48 && c <= 57 { out = out + [c - 48]; }
    }
    ret out;
}
fn main() -> Void {
