    let lo: Int = 0;
    let width: Int = 10;
    let nbins: Int = 3;
    let counts: Int[] = [];
    loop b in 0..nbins { counts = counts + [0]; }
    let outside: Int = 0;
    loop i in 0..length(vals) {
        let v: Int = vals[i];
        let b: Int = (v - lo) / width;
        if v == lo + width * nbins { b = nbins - 1; }
        if v < lo || v > lo + width * nbins { outside = outside + 1; }
        else { counts[b] = counts[b] + 1; }
    }
    fx {
        loop b in 0..nbins {
            let a: Int = lo + b * width;
            let z: Int = a + width;
            let closer: Text = ")";
            if b == nbins - 1 { closer = "]"; }
            print("[", a, ",", z, closer, " ", counts[b], " ");
            loop k in 0..counts[b] { print("#"); }
            println("");
        }
        println("outside=", outside, " total=", length(vals));
    }
}

@pure
fn plural(n: Int, unit: Text) -> Text {
    if n == 1 { ret int_to_text(n) + " " + unit; }
    ret int_to_text(n) + " " + unit + "s";
}
@pure
fn fmt(total: Int) -> Text {
    if total == 0 { ret "0 seconds"; }
    let d: Int = total / 86400;
    let rem: Int = total - d * 86400;
    let h: Int = rem / 3600;
    rem = rem - h * 3600;
    let m: Int = rem / 60;
    let s: Int = rem - m * 60;
    let parts: Text[] = [];
    if d > 0 { parts = parts + [plural(d, "day")]; }
    if h > 0 { parts = parts + [plural(h, "hour")]; }
    if m > 0 { parts = parts + [plural(m, "minute")]; }
    if s > 0 { parts = parts + [plural(s, "second")]; }
    let out: Text = "";
    loop i in 0..length(parts) {
        if i == 0 { out = parts[i]; }
        else {
            if i == length(parts) - 1 { out = out + " and " + parts[i]; }
            else { out = out + ", " + parts[i]; }
        }
    }
    ret out;
}
fn main() -> Void {
    let secs: Int[] = [0, 1, 61, 3661, 90061, 7200, 86400];
    fx {
        loop i in 0..length(secs) { println(secs[i], " -> ", fmt(secs[i])); }
    }
}

@pure
fn isLeap(y: Int) -> Bool {
    if y % 400 == 0 { ret true; }
    if y % 100 == 0 { ret false; }
    if y % 4 == 0 { ret true; }
    ret false;
}
@pure
fn daysInMonth(y: Int, m: Int) -> Int {
    if m == 2 { if isLeap(y) { ret 29; } ret 28; }
    if m == 4 || m == 6 || m == 9 || m == 11 { ret 30; }
    ret 31;
}
@pure
fn dayOfYear(y: Int, m: Int, d: Int) -> Int {
    let n: Int = d;
    loop k in 1..m { n = n + daysInMonth(y, k); }
    ret n;
}
