@pure
fn cmpInt(a: Int, b: Int) -> Int {
    if a < b { ret -1; }
    if a > b { ret 1; }
    ret 0;
}
type Ver { major: Int = 0; minor: Int = 0; patch: Int = 0; pre: Text = ""; }
@pure
fn parseVer(s: Text) -> Ver {
    let dash: Int = pos("-", s);
    let core: Text = s;
    let pre: Text = "";
    if dash != -1 { core = s[0..dash]; pre = s[dash + 1..string_len(s)]; }
    let parts: Text[] = split(core, ".");
    let mj: Int = 0;
    let mn: Int = 0;
    let pt: Int = 0;
    if length(parts) > 0 { mj = parse_int(parts[0]); }
    if length(parts) > 1 { mn = parse_int(parts[1]); }
    if length(parts) > 2 { pt = parse_int(parts[2]); }
    ret new Ver { major: mj, minor: mn, patch: pt, pre: pre };
}
@pure
fn cmpVer(a: Ver, b: Ver) -> Int {
    let c: Int = cmpInt(a.major, b.major);
    if c != 0 { ret c; }
    c = cmpInt(a.minor, b.minor);
    if c != 0 { ret c; }
    c = cmpInt(a.patch, b.patch);
    if c != 0 { ret c; }
    let ap: Bool = string_len(a.pre) > 0;
    let bp: Bool = string_len(b.pre) > 0;
    if ap && !bp { ret -1; }
    if !ap && bp { ret 1; }
    if !ap && !bp { ret 0; }
    if a.pre < b.pre { ret -1; }
    if a.pre > b.pre { ret 1; }
    ret 0;
}
fn main() -> Void {
    let vs: Text[] = ["1.2.10", "1.2.9", "1.3.0-alpha", "1.3.0", "1.3.0-beta", "0.9.9"];
    let parsed: Ver[] = [];
    loop i in 0..length(vs) { parsed = parsed + [parseVer(vs[i])]; }
    let order: Int[] = [];
    loop i in 0..length(vs) { order = order + [i]; }
    loop i in 0..length(order) {
        loop j in 0..(length(order) - 1 - i) {
            if cmpVer(parsed[order[j]], parsed[order[j + 1]]) > 0 {
                let t: Int = order[j]; order[j] = order[j + 1]; order[j + 1] = t;
            }
        }
    }
    fx {
        loop k in 0..length(order) { println(k, ": ", vs[order[k]]); }
        println("lowest=", vs[order[0]], " highest=", vs[order[length(order) - 1]]);
    }
}

