@pure
fn toRoman(n: Int) -> Text {
    let vals: Int[] = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
    let syms: Text[] = ["M","CM","D","CD","C","XC","L","XL","X","IX","V","IV","I"];
    let out: Text = "";
    let v: Int = n;
    loop i in 0..length(vals) {
        loop k in 0..4000 {
            if v >= vals[i] { out = out + syms[i]; v = v - vals[i]; }
        }
    }
    ret out;
}
@pure
fn fromRoman(s: Text) -> Int {
    let total: Int = 0;
    loop i in 0..string_len(s) {
        let c: Text = s[i..i + 1];
        let v: Int = 0;
        if string_eq(c, "I") { v = 1; }
        if string_eq(c, "V") { v = 5; }
        if string_eq(c, "X") { v = 10; }
        if string_eq(c, "L") { v = 50; }
        if string_eq(c, "C") { v = 100; }
        if string_eq(c, "D") { v = 500; }
        if string_eq(c, "M") { v = 1000; }
        let nxt: Int = 0;
        if i + 1 < string_len(s) {
            let d: Text = s[i + 1..i + 2];
            if string_eq(d, "I") { nxt = 1; }
            if string_eq(d, "V") { nxt = 5; }
            if string_eq(d, "X") { nxt = 10; }
            if string_eq(d, "L") { nxt = 50; }
            if string_eq(d, "C") { nxt = 100; }
            if string_eq(d, "D") { nxt = 500; }
            if string_eq(d, "M") { nxt = 1000; }
        }
        if v < nxt { total = total - v; } else { total = total + v; }
    }
    ret total;
}
