@pure
fn ceilDiv(a: Int, b: Int) -> Int {
    let q: Int = a / b;
    if q * b < a { ret q + 1; }
    ret q;
}
fn main() -> Void {
    let raw: Int[] = [15, 20, 35, 40, 50, 20];
    let xs: Int[] = [];
    loop i in 0..length(raw) { xs = xs + [raw[i]]; }
    loop i in 0..length(xs) {
        loop j in 0..(length(xs) - 1 - i) {
            if xs[j] > xs[j + 1] { let t: Int = xs[j]; xs[j] = xs[j + 1]; xs[j + 1] = t; }
        }
    }
    let ps: Int[] = [0, 25, 50, 75, 100, 30];
    let n: Int = length(xs);
    fx {
        print("sorted:");
        loop i in 0..n { print(" ", xs[i]); }
        println("");
        loop k in 0..length(ps) {
            let p: Int = ps[k];
            let rank: Int = ceilDiv(p * n, 100);
            if rank < 1 { rank = 1; }
            println("p", p, " rank=", rank, " value=", xs[rank - 1]);
        }
        println("n=", n);
    }
}
